import {validBoard,validateLatex} from './math-board-model.js';
export const ART_DB='dormi.math-board.v1',ART_STORE='drafts',ART_KEY='current',MAX_ART_BLOB=2*1024*1024;
export function validateMathDraft(r){if(!r||r.version!==1)return r?.version>1?'future-version':'corrupt';if(r.width!==720||r.height!==440||!validBoard(r.board)||typeof r.editorLatex!=='string'||(r.editorLatex!==''&&!validateLatex(r.editorLatex,{draft:true}).ok)||!(r.baseBlob instanceof Blob)||r.baseBlob.type!=='image/png'||!r.baseBlob.size||r.baseBlob.size>MAX_ART_BLOB||!Number.isSafeInteger(r.revision)||r.revision<1||!Number.isFinite(r.updatedAt))return 'corrupt';return 'valid';}
/** One local draft, separate from progress and photo storage. DB closes after every operation. */
export function createMathStorage({indexedDB=globalThis.indexedDB,timeoutMs=3000,canWrite=()=>true}={}){
 async function open(){if(!indexedDB)return {status:'unavailable'};return new Promise(resolve=>{let done=false,request;const finish=value=>{if(done){value.db?.close();return;}done=true;clearTimeout(timer);resolve(value);},timer=setTimeout(()=>finish({status:'unavailable'}),timeoutMs);try{request=indexedDB.open(ART_DB,1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains(ART_STORE))request.result.createObjectStore(ART_STORE);};request.onerror=()=>finish({status:request.error?.name==='VersionError'?'future-version':'unavailable'});request.onblocked=()=>finish({status:'blocked'});request.onsuccess=()=>{const db=request.result;db.onversionchange=()=>db.close();finish({status:'ready',db});};}catch{finish({status:'unavailable'});}});}
 async function run(mode,operation){if(mode==='readwrite'&&!canWrite())return {status:'read-only'};const opened=await open();if(!opened.db)return opened;const db=opened.db;if(mode==='readwrite'&&!canWrite()){db.close();return {status:'read-only'};}return new Promise(resolve=>{let tx,done=false,result={status:'failed'};const finish=value=>{if(done)return;done=true;clearTimeout(timer);db.close();resolve(value);},timer=setTimeout(()=>{try{tx?.abort();}catch{}finish({status:'failed'});},timeoutMs);try{tx=db.transaction(ART_STORE,mode);tx.oncomplete=()=>finish(result);tx.onabort=tx.onerror=()=>finish(result.status==='read-only'||result.status==='conflict'||result.status==='future-version'||result.status==='corrupt'?result:{status:'failed'});operation(tx.objectStore(ART_STORE),value=>result=value,tx);}catch{finish({status:'failed'});}});}
 return {
  read:()=>run('readonly',(store,set)=>{const req=store.get(ART_KEY);req.onsuccess=()=>{const r=req.result;if(r===undefined){set({status:'empty',revision:0});return;}const status=validateMathDraft(r);set(status==='valid'?{status:'loaded',revision:r.revision,record:r}:{status});};}),
  write(record,expectedRevision){const candidate={...record,version:1,width:720,height:440,revision:expectedRevision+1,updatedAt:Date.now()};if(record?.baseBlob?.size>MAX_ART_BLOB)return Promise.resolve({status:'too-large'});if(validateMathDraft(candidate)!=='valid')return Promise.resolve({status:'corrupt'});return run('readwrite',(store,set,tx)=>{const req=store.get(ART_KEY);req.onsuccess=()=>{if(!canWrite()){set({status:'read-only'});tx.abort();return;}const current=req.result,status=current===undefined?'valid':validateMathDraft(current);if(status!=='valid'){set({status});tx.abort();return;}if((current?.revision??0)!==expectedRevision){set({status:'conflict'});tx.abort();return;}store.put(candidate,ART_KEY);set({status:'saved',revision:candidate.revision});};});},
  clear:()=>run('readwrite',(store,set)=>{store.delete(ART_KEY);set({status:'cleared'});})
 };
}
